// One job per product × language, with that language's glossary rules attached.
const LANGS = { DE: 'German', FR: 'French', PL: 'Polish', ES: 'Spanish', IT: 'Italian' };

const parse = o => (typeof o === 'string' ? JSON.parse(o) : o);
const products = $('Limit').all().map(i => i.json);
const enriched = $('Enrich EN').all().map(i => parse(i.json.output ?? i.json));
const glossary = $('Get Glossary').all().map(i => i.json);

const keepTerms = glossary.filter(g => g.rule === 'keep').map(g => g.term_en);

const jobs = [];
products.forEach((p, idx) => {
  const en = enriched[idx];
  for (const [code, name] of Object.entries(LANGS)) {
    const fixed = glossary
      .filter(g => g.rule === 'fixed' && g[code])
      .map(g => ({ en: g.term_en, target: g[code] }));
    jobs.push({
      json: {
        sku: p.sku,
        name_en: p.name_en,
        specs: p.specs,
        keywords_en: p.keywords_en,
        lang: code,
        lang_name: name,
        en,
        en_json: JSON.stringify(en),
        keep_terms: keepTerms,
        fixed_terms: fixed,
        glossary_text: [
          'Never translate: ' + keepTerms.join(', '),
          ...fixed.map(f => `Always translate "${f.en}" as "${f.target}"`),
        ].join('\n'),
      },
    });
  }
});
return jobs;

// Rule checks that need no AI: lengths, glossary terms, HTML tags.
const LIMITS = { seo_title: 70, meta_title: 60, meta_description: 155, alt_text: 125 };
const norm = s => String(s ?? '').toLowerCase().replace(/[‘’`]/g, "'");
// Rough stem so inflected forms still match (samonawadniająca -> samonawadniającej).
const stem = t => { const s = norm(t); return s.length > 6 ? s.slice(0, -2) : s; };
const parse = o => (typeof o === 'string' ? JSON.parse(o) : o);

const jobs = $('Build Language Jobs').all().map(i => i.json);

return $input.all().map((item, idx) => {
  const job = jobs[idx];
  const out = parse(item.json.output ?? item.json);
  // Unwrap inline tags (<em>, <strong>, ...) instead of failing on them: the text stays, the markup goes.
  out.description_html = String(out.description_html ?? '').replace(/<\/?(em|strong|b|i|span)\b[^>]*>/gi, '');
  const issues = [];

  for (const [field, max] of Object.entries(LIMITS)) {
    const len = String(out[field] ?? '').length;
    if (!len) issues.push(`${field}: empty`);
    else if (len > max) issues.push(`${field}: ${len}/${max} chars`);
  }
  const bullets = Array.isArray(out.bullets) ? out.bullets : [];
  if (bullets.length !== 3) issues.push(`bullets: ${bullets.length} instead of 3`);
  bullets.forEach((b, n) => { if (b.length > 90) issues.push(`bullet ${n + 1}: ${b.length}/90 chars`); });

  const enText = norm(job.en_json);
  const localText = norm(JSON.stringify(out));
  for (const term of job.keep_terms) {
    if (enText.includes(norm(term)) && !localText.includes(norm(term))) {
      issues.push(`glossary: "${term}" missing or translated`);
    } else if (enText.includes(`'${norm(term)}'`) && !localText.includes(`'${norm(term)}'`)) {
      issues.push(`glossary: cultivar '${term}' lost its quotes`);
    }
  }
  for (const f of job.fixed_terms) {
    if (enText.includes(norm(f.en)) && !localText.includes(stem(f.target))) {
      issues.push(`glossary: "${f.en}" should be "${f.target}"`);
    }
  }

  const html = String(out.description_html ?? '');
  const tags = html.match(/<\/?[a-z0-9]+/gi) ?? [];
  const unexpected = [...new Set(tags.filter(t => !/^<\/?(p|ul|li)$/i.test(t)))];
  if (unexpected.length) issues.push(`html: unexpected tags ${unexpected.join(' ')}`);
  for (const t of ['p', 'ul', 'li']) {
    const open = (html.match(new RegExp(`<${t}[\\s>]`, 'gi')) ?? []).length;
    const close = (html.match(new RegExp(`</${t}>`, 'gi')) ?? []).length;
    if (open !== close) issues.push(`html: <${t}> opened ${open}, closed ${close}`);
  }

  return {
    json: {
      ...job,
      local: out,
      local_json: JSON.stringify(out),
      validation_issues: issues,
      validation_ok: issues.length === 0,
    },
  };
});

