// Flatten everything into one sheet row per product × language and set its status.
const parse = o => (typeof o === 'string' ? JSON.parse(o) : o);
const validated = $('Validate').all().map(i => i.json);

return $input.all().map((item, idx) => {
  const v = validated[idx];
  const qa = parse(item.json.output ?? item.json);
  const l = v.local;
  const ok = v.validation_ok && Number(qa.score) >= 4;
  return {
    json: {
      sku: v.sku,
      lang: v.lang,
      seo_title: l.seo_title,
      meta_title: l.meta_title,
      meta_description: l.meta_description,
      alt_text: l.alt_text,
      bullets: (l.bullets ?? []).join(' | '),
      description_html: l.description_html,
      local_keywords: (l.local_keywords ?? []).join(' | '),
      qa_score: qa.score,
      qa_issues: (qa.issues ?? []).join(' | '),
      back_translation: qa.back_translation,
      validation_issues: v.validation_issues.join(' | '),
      status: ok ? 'done' : 'needs_review',
    },
  };
});

// One status per product: done only if all its languages are done.
const bySku = {};
for (const { json } of $input.all()) {
  const prev = bySku[json.sku];
  bySku[json.sku] = prev === 'needs_review' || json.status === 'needs_review' ? 'needs_review' : 'done';
}
return Object.entries(bySku).map(([sku, status]) => ({ json: { sku, status } }));

// Magento 2 import: one row per product per store view, only rows that passed QA.
// store_view_code must match the store view codes in Magento (Stores > All Stores).
const STORE_VIEW = { DE: 'de', FR: 'fr', PL: 'pl', ES: 'es', IT: 'it' };

return $input.all()
  .filter(({ json }) => json.status === 'done')
  .map(({ json: r }) => ({
    json: {
      sku: r.sku,
      store_view_code: STORE_VIEW[r.lang],
      name: r.seo_title,
      description: r.description_html,
      short_description: '<ul>' + r.bullets.split(' | ').map(b => `<li>${b}</li>`).join('') + '</ul>',
      meta_title: r.meta_title,
      meta_description: r.meta_description,
      meta_keywords: r.local_keywords.split(' | ').join(', '),
    },
  }));

// Shopify translations CSV structure. In a real store Identification is the product ID
// from the store's own translation export; in this demo the SKU is a placeholder.
const FIELDS = {
  title: 'seo_title',
  body_html: 'description_html',
  meta_title: 'meta_title',
  meta_description: 'meta_description',
};

const rows = [];
for (const { json: r } of $input.all()) {
  if (r.status !== 'done') continue;
  for (const [field, key] of Object.entries(FIELDS)) {
    rows.push({
      json: {
        'Type': 'PRODUCT',
        'Identification': `SKU:${r.sku}`,
        'Field': field,
        'Locale': r.lang.toLowerCase(),
        'Market': '',
        'Status': '',
        'Default content': '',
        'Translated content': r[key],
      },
    });
  }
}
return rows;
